#!/usr/bin/env node
// Reads the single-file Phaser build and embeds it as a TS string constant
// that the mobile app's WebView can load via `source={{ html: GAME_HTML }}`.
// Runs automatically via the root "postinstall" script, and via
// "npm run build:game" whenever the game-engine source changes.
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const rootDir = dirname(fileURLToPath(import.meta.url)) + "/..";
const distHtmlPath = resolve(rootDir, "packages/game-engine/dist/index.html");
const outPath = resolve(rootDir, "apps/mobile/src/game/gameBundle.generated.ts");

if (!existsSync(distHtmlPath)) {
  console.error(`[embed-game-bundle] Missing build output at ${distHtmlPath}.`);
  console.error(`[embed-game-bundle] Run "npm run build --workspace=@battle-formation/game-engine" first.`);
  process.exit(1);
}

const html = readFileSync(distHtmlPath, "utf-8");
const escaped = html.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${");

mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(
  outPath,
  `// AUTO-GENERATED by scripts/embed-game-bundle.mjs - do not edit by hand.\n` +
    `// Source: packages/game-engine (run "npm run build:game" to regenerate).\n` +
    `export const GAME_HTML = \`${escaped}\`;\n`
);

console.log(`[embed-game-bundle] Wrote ${outPath} (${(html.length / 1024).toFixed(1)} KB)`);
